-- Physical Education with Personal Fitness final module. Run seed_pe_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'physical-education';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Personal Fitness Plan and Portfolio$j$, $j${"prompt": "Create a personal fitness plan and portfolio of at least 600 words with your activity log attached, and prepare a short presentation of its main ideas. Get approval from a parent or guardian before you begin, and ask a doctor if you have any health concern. Write complete sentences and label each part. First Corinthians 6:19 says, What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?\n\nPart 1: Starting Point. Describe your health habits and your results on at least three assessments, such as a timed walk or run, resting heart rate, push ups or curl ups, and the sit and reach.\nPart 2: Goals. Write at least three SMART goals, including at least one for cardiorespiratory fitness, one for strength or endurance and one for flexibility, health or wellness.\nPart 3: The Plan. Design a four week program that follows the FITT principle, with a warm up and cool down, aerobic, strength and flexibility work, rest days and the national guideline of 60 minutes of daily activity for teens.\nPart 4: Nutrition, Sleep and Wellness. Describe your plan for hydration, meals and snacks, sleep and stress, and one step to avoid tobacco, alcohol and drugs.\nPart 5: Safety. Explain how you will handle Florida heat, prevent injury and respond if you or someone else is hurt.\nPart 6: Results and Reflection. Attach your activity log for at least four weeks. Report your retest results, what you learned and what you will change.\nPart 7: Scripture and Service. Connect your plan to a passage of Scripture in the King James Version and describe one way you will use your health to serve others.\nPart 8: Presentation Plan. Write a three part outline and an opening line for a three minute talk.", "rubric": "100 points. Part 1, starting point: 10 points. Part 2, goals: 10 points. Part 3, the plan and use of FITT: 20 points. Part 4, nutrition, sleep and wellness: 15 points. Part 5, safety: 10 points. Part 6, results, activity log and reflection: 15 points. Part 7, Scripture and service: 5 points. Part 8, presentation plan: 5 points. Grammar, conventions and respectful tone: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Personal Fitness Plan and Portfolio$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Physical Education with Personal Fitness$j$, $j${"questions": [{"q": "Teens should get at least how much moderate to vigorous activity each day?", "options": ["3 hours", "5 minutes", "10 minutes", "60 minutes"]}, {"q": "The ability of the heart, lungs and blood vessels to supply oxygen during long activity is:", "options": ["Flexibility", "Cardiorespiratory endurance", "Reaction time", "Agility"]}, {"q": "In the FITT principle, the F stands for:", "options": ["Fitness", "Frequency", "Force", "Fat"]}, {"q": "A rough estimate of maximum heart rate is:", "options": ["100 plus your age", "220 minus your age", "Your age times 3", "60 minus your age"]}, {"q": "A sign of heat stroke that needs an immediate 911 call is:", "options": ["A small scrape", "Confusion and very hot skin", "A sore muscle", "Mild thirst"]}, {"q": "When the biceps contracts, the triceps:", "options": ["Disappears", "Turns to bone", "Relaxes", "Contracts fully"]}, {"q": "A beginner strength routine should include:", "options": ["Good form and rest between sets", "Steroids", "Holding the breath", "A maximum lift without a spotter"]}, {"q": "Static stretching is best done:", "options": ["Bouncing on cold muscles", "Never", "Only before sleep", "After exercise when muscles are warm"]}, {"q": "In the RICE method, the I stands for:", "options": ["Ice", "Intensity", "Inflammation", "Injury"]}, {"q": "MyPlate suggests filling about half your plate with:", "options": ["Fruits and vegetables", "Soda", "Fried foods", "Sweets"]}, {"q": "A sign of good hydration is urine that is:", "options": ["Pale yellow", "Dark yellow", "Brown", "Bright orange"]}, {"q": "Teens need about how many hours of sleep each night?", "options": ["12 to 14", "5 to 6", "3 to 4", "8 to 10"]}, {"q": "Nicotine in cigarettes and vapes is:", "options": ["Highly addictive", "Harmless", "A vitamin", "A fruit"]}, {"q": "A person who is worried about their eating or mood should:", "options": ["Wait without telling anyone", "Hide it", "Talk with a trusted adult, counselor or doctor", "Take supplements"]}, {"q": "First Timothy 4:8 says that godliness is:", "options": ["Only for adults", "Profitable unto all things", "Profitable in nothing", "A waste of time"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Physical Education with Personal Fitness$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,1,1,2,0,3,0,0,0,3,0,2,1}'::int[], array[$j$The national guideline is 60 minutes a day for ages 6 to 17.$j$,$j$It is the first of the health related components.$j$,$j$FITT stands for frequency, intensity, time and type.$j$,$j$It is only an estimate, and individuals differ.$j$,$j$Heat stroke is a medical emergency.$j$,$j$Muscles work in opposing pairs.$j$,$j$Safety and form come first.$j$,$j$Warm muscles stretch more safely.$j$,$j$RICE means rest, ice, compression and elevation.$j$,$j$Fruits and vegetables belong on half the plate.$j$,$j$Pale yellow suggests that you are drinking enough.$j$,$j$Sleep supports growth, mood and learning.$j$,$j$Nicotine is the addictive drug in tobacco and vaping products.$j$,$j$Help is available and recovery is possible.$j$,$j$Exercise is useful, but godliness is profitable unto all things.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Physical Education with Personal Fitness$j$ on conflict (item_id) do nothing;
end
$seed$;
